  font-size: 1.125rem;
  font-weight: 600;
  letter-spacing: 0.2px;
}

.modal-desc {
  margin: var(--space-2) 0 var(--space-5);
  color: var(--text-muted);
  font-size: 0.95rem;
}

.modal-desc strong {
  color: var(--text);
  font-weight: 600;
}

.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: var(--space-2);
