const { useState, useEffect, useRef, useCallback, useId } = React;

function TrashIcon(props) {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor"
      strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"
      aria-hidden="true" {...props}>
      <path d="M3 6h18" />
      <path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" />
      <path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6" />
      <path d="M10 11v6" />
      <path d="M14 11v6" />
    </svg>
  );
}

function DownloadIcon(props) {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor"
      strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"
      aria-hidden="true" {...props}>
      <path d="M12 3v12" />
      <path d="M7 10l5 5 5-5" />
      <path d="M5 21h14" />
    </svg>
  );
}

function ConfirmDeleteDialog({ open, imageName, onCancel, onConfirm }) {
  const dialogRef = useRef(null);
  const cancelRef = useRef(null);
  const previousFocusRef = useRef(null);
  const titleId = useId();
  const descId = useId();

  // Focus management & Escape handling
  useEffect(() => {
    if (!open) return;

    previousFocusRef.current = document.activeElement;

    // Focus the safer "Cancel" action first
    requestAnimationFrame(() => {
      cancelRef.current?.focus();
    });

    const onKeyDown = (e) => {
      if (e.key === "Escape") {
        e.stopPropagation();
        onCancel();
        return;
      }
      if (e.key === "Tab") {
        const root = dialogRef.current;
        if (!root) return;
        const focusables = root.querySelectorAll(
          'button:not([disabled]), [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
        );
        if (focusables.length === 0) return;
        const first = focusables[0];
        const last = focusables[focusables.length - 1];
        if (e.shiftKey && document.activeElement === first) {
          e.preventDefault();
          last.focus();
        } else if (!e.shiftKey && document.activeElement === last) {
          e.preventDefault();
          first.focus();
        }
      }
    };

    document.addEventListener("keydown", onKeyDown);
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";

    return () => {
      document.removeEventListener("keydown", onKeyDown);
      document.body.style.overflow = prevOverflow;
      const prev = previousFocusRef.current;
      if (prev && typeof prev.focus === "function") prev.focus();
    };
  }, [open, onCancel]);

  if (!open) return null;

  const onBackdropMouseDown = (e) => {
    if (e.target === e.currentTarget) onCancel();
  };

  return (
    <div
      className="modal-backdrop"
      onMouseDown={onBackdropMouseDown}
    >
      <div
        ref={dialogRef}
        className="modal"
        role="alertdialog"
        aria-modal="true"
        aria-labelledby={titleId}
        aria-describedby={descId}
      >
        <div className="modal-head">
          <div className="modal-icon" aria-hidden="true">
            <TrashIcon />
          </div>
          <h2 id={titleId} className="modal-title">
            Delete this image?
          </h2>
        </div>
        <p id={descId} className="modal-desc">
          <strong>{imageName}</strong> will be permanently removed from your
          library. This action cannot be undone.
        </p>
        <div className="modal-actions">
          <button
            ref={cancelRef}
            type="button"
            className="btn btn-secondary"
            onClick={onCancel}
          >
            Cancel
          </button>
          <button
            type="button"
            className="btn btn-danger-solid"
            onClick={onConfirm}
          >
            <TrashIcon className="icon" />
            Delete image
          </button>
        </div>
      </div>
    </div>
  );
}

function StatusRegion({ message }) {
  return (
    <div
      role="status"
      aria-live="polite"
      style={{
        position: "absolute",
        width: 1,
        height: 1,
        margin: -1,
        padding: 0,
        overflow: "hidden",
        clip: "rect(0 0 0 0)",
        whiteSpace: "nowrap",
        border: 0,
      }}
    >
      {message}
    </div>
  );
}

function ImagePreviewPage() {
  const [open, setOpen] = useState(false);
  const [deleted, setDeleted] = useState(false);
  const [status, setStatus] = useState("");

  const image = {
    name: "Aurora 2024.jpg",
    captured: "Captured Mar 12, 2024 · 4.2 MB · 4032 × 3024",
    src:
      "https://images.unsplash.com/photo-1483728642387-6c3bdd6c93e5?auto=format&fit=crop&w=1600&q=80",
    alt:
      "Green and purple aurora borealis arcing across a starry night sky above a snowy mountain ridge.",
  };

  const handleConfirm = useCallback(() => {
    setOpen(false);
    setDeleted(true);
    setStatus(`${image.name} was deleted from your library.`);
  }, [image.name]);

  const handleCancel = useCallback(() => {
    setOpen(false);
  }, []);

  return (
    <>
      <header className="app-header">
        <div className="app-header-inner">
          <div className="brand" aria-label="Lumen Photos">
            <span className="brand-mark" aria-hidden="true" />
            <span>Lumen Photos</span>
          </div>
          <nav aria-label="Breadcrumb" className="crumbs">
            <a href="#library">Library</a>
            <span className="sep" aria-hidden="true">/</span>
            <span aria-current="page">{image.name}</span>
          </nav>
        </div>
      </header>

      <main id="main">
        <h1 className="visually-hidden" style={{
          position: "absolute", width: 1, height: 1, margin: -1,
          padding: 0, overflow: "hidden", clip: "rect(0 0 0 0)",
          whiteSpace: "nowrap", border: 0,
        }}>
          Image preview: {image.name}
        </h1>

        <article className="preview-card" aria-labelledby="preview-title">
          <div className="preview-image-wrap">
            {!deleted && (
              <img
                className="preview-image"
                src={image.src}
                alt={image.alt}
              />
            )}
            {deleted && (
              <div
                style={{
                  height: "100%",
                  display: "grid",
                  placeItems: "center",
                  color: "var(--text-muted)",
                  background:
                    "repeating-linear-gradient(45deg, #11141b, #11141b 12px, #161a23 12px, #161a23 24px)",
                }}
              >
                Image deleted
              </div>
            )}
          </div>
          <div className="preview-meta">
            <div>
              <h2 id="preview-title" className="preview-title">
                {image.name}
              </h2>
              <p className="preview-sub">{image.captured}</p>
            </div>
            <div className="preview-actions">
              <button type="button" className="btn btn-secondary" disabled={deleted}>
                <DownloadIcon className="icon" />
                Download
              </button>
              <button
                type="button"
                className="btn btn-danger trigger"
                onClick={() => setOpen(true)}
                disabled={deleted}
                aria-haspopup="dialog"
                aria-label={`Delete image: ${image.name}`}
              >
                <TrashIcon className="icon" />
                Delete
              </button>
            </div>
          </div>
        </article>
      </main>

      <ConfirmDeleteDialog
        open={open}
        imageName={image.name}
        onCancel={handleCancel}
        onConfirm={handleConfirm}
      />

      <StatusRegion message={status} />
    </>
  );
}

const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(<ImagePreviewPage />);

